export const inboxInteractionActive=()=>threadHolding||chatComposerBusy(document)||Boolean(document.querySelector('.bubble-wrap:hover,.bubble-wrap:focus-within,.message-tools:hover,.message-tools:focus-within,.message-more[open],.chat-message-menu-popup:hover,.chat-message-menu-popup:focus-within,.chat-menu[open],.chat-image-viewer[open],.chat-topic-bar:hover,.chat-topic-bar:focus-within,.chat-header-tags:hover,.chat-header-tags:focus-within'));
function initSendHold(){
 let hold=null,suppressUntil=0;
 const cancel=()=>{if(hold)clearTimeout(hold.timer);hold=null;threadHolding=false;};
 document.addEventListener('pointerdown',event=>{const button=event.target.closest('#reply-form [type=submit]');if(!button||event.button!==0||button.disabled)return;cancel();threadHolding=true;hold={x:event.clientX,y:event.clientY,timer:setTimeout(()=>{rememberInboxDraft();const c=active();if(!c)return cancel();const d=draft(c.id);d.note=!d.note;saveDrafts();suppressUntil=Date.now()+1200;cancel();paint();H.toast(d.note?'Chế độ ghi chú nội bộ · Bấm để lưu':'Chế độ gửi tin cho khách');},650)};});
 document.addEventListener('pointermove',event=>{if(hold&&Math.hypot(event.clientX-hold.x,event.clientY-hold.y)>10)cancel();});
 for(const type of ['pointerup','pointercancel'])document.addEventListener(type,cancel,true);
 document.addEventListener('click',event=>{if(Date.now()<suppressUntil&&event.target.closest('#reply-form [type=submit]')){event.preventDefault();event.stopImmediatePropagation();}},true);
 document.addEventListener('contextmenu',event=>{if(event.target.closest('#reply-form [type=submit]'))event.preventDefault();});
}
let deletePreviewRequest=0;
async function deleteDialog(ids){const request=++deletePreviewRequest;try{pendingDelete=ids.map(id=>H.state.conversations.find(c=>c.id===id)).filter(Boolean).map(c=>({id:c.id,version:c.version}));if(!pendingDelete.length)return;pendingDeleteToken='';H.modal('Xóa hội thoại và dữ liệu khách hàng','<p id="chat-delete-loading" role="status">Đang kiểm tra phạm vi dữ liệu và trạng thái học viên…</p>');const preview=await H.api('/chat/delete/preview',{method:'POST',body:{items:pendingDelete}});if(request!==deletePreviewRequest||!document.querySelector('#chat-delete-loading'))return;pendingDeleteToken=preview.token;H.modal('Xóa hội thoại và dữ liệu khách hàng',`<form id="chat-delete-form"><p>Xóa vĩnh viễn hồ sơ khách/học viên đại diện, tiến trình học, lịch sử mua sắm, tin nhắn và dữ liệu liên quan trong hệ thống và Supabase.</p><table><thead><tr><th>Khách hàng / học viên</th><th>Trạng thái hiện tại</th></tr></thead><tbody>${preview.profiles.map(p=>`<tr><td>${e(p.name)}</td><td>${e(p.stageName)}</td></tr>`).join('')}</tbody></table><p>Phạm vi: ${preview.conversationCount} hội thoại liên quan; ${preview.recordCount} bản ghi trên hệ thống.</p>${preview.requiresStageConfirm?'<label><input name="confirmStage" type="checkbox" required> Tôi đã kiểm tra trạng thái học viên và đồng ý xóa toàn bộ dữ liệu liên quan.</label>':''}<p>Tin nhắn trên nền tảng gốc không bị xóa. Tin mới về sau tạo hồ sơ mới.</p><button type="submit" class="btn danger">Xác nhận xóa vĩnh viễn</button></form>`);}catch(err){if(request===deletePreviewRequest&&document.querySelector('#chat-delete-loading'))H.closeModal();H.toast(err.message);}}
export function forgetInboxConversations(ids){for(const id of ids){drafts.delete(id);selected.delete(id);}if(!selected.size)selectionMode=false;saveDrafts();}

export function compactChatHead(){
 if(H?.route()!=='inbox')return;const head=$('.chat-head'),panel=head?.querySelector('.chat-actions .chat-menu-panel');if(!panel)return;
 const identity=head.querySelector('.row:first-child>div:last-child');if(!identity)return;
 const meta=document.createElement('div');meta.className='chat-head-meta';
 for(const el of [identity.querySelector('.learner-progress-text'),identity.querySelector('small.muted'),identity.querySelector('.chat-assigned')])if(el){el.title=el.textContent;if(el.classList.contains('chat-assigned'))el.textContent=el.textContent.replace('Phụ trách: ','');meta.append(el);}identity.append(meta);
 const tools=document.createElement('div');tools.className='chat-head-tools';const info=head.querySelector('[data-bot=info]');if(info){info.innerHTML=icon('help',18);info.title='Thông tin AI';info.setAttribute('aria-label','Thông tin AI');}
 for(const el of head.querySelectorAll('.chat-name-icons button,[data-bot=toggle],[data-bot=info]'))tools.append(el);
 if(!tools.querySelector('[data-care=profile]'))tools.insertAdjacentHTML('beforeend',`<button type="button" class="chat-tool" data-care="profile" data-id="${e(active().customerId)}" title="Hồ sơ / Đơn" aria-label="Xem hồ sơ khách">${icon('users',18)}</button>`);
 tools.insertAdjacentHTML('beforeend',tool('Tạo lịch hẹn','reminders','calendar',active().id));head.querySelector('.care-profile-open')?.remove();head.querySelector('[data-action=customer-detail]')?.remove();
 head.querySelector('.row:nth-child(2)')?.prepend(tools);

 head.querySelector('[data-action=resolve-chat]')?.remove();
 const summary=head.querySelector('.chat-actions summary');summary.innerHTML=icon('more',18);summary.setAttribute('aria-label','Tùy chọn hội thoại');summary.title='Tùy chọn hội thoại';if(openMenus.includes('Tùy chọn hội thoại'))summary.parentElement.open=true;
}
function initThreadHold(){
 let hold=null,heldId='',until=0;const cancel=()=>{if(hold)clearTimeout(hold.timer);hold=null;threadHolding=false;};
 const toggle=id=>{if(selected.has(id))selected.delete(id);else if(selected.size<100)selected.add(id);else H.toast('Chọn tối đa 100 hội thoại mỗi lần.',true);redraw();};
 document.addEventListener('pointerdown',event=>{cancel();const row=event.target.closest('.conversation-item[data-id]');if(H.route()!=='inbox'||!row||event.button!==0||event.target.closest('input,button,a'))return;const id=row.dataset.id;threadHolding=true;if(event.pointerType==='mouse')event.preventDefault();hold={x:event.clientX,y:event.clientY,pointerId:event.pointerId,timer:setTimeout(()=>{if(H.route()!=='inbox'||!H.state.conversations.some(c=>c.id===id)){cancel();return;}heldId=id;until=Date.now()+1000;cancel();selectionMode=true;if(selected.size<100)selected.add(id);redraw();},600)};});
 document.addEventListener('pointermove',event=>{if(hold&&(event.pointerId!==hold.pointerId||Math.hypot(event.clientX-hold.x,event.clientY-hold.y)>10))cancel();});
 for(const type of ['pointerup','pointercancel'])document.addEventListener(type,cancel,true);
 document.addEventListener('scroll',event=>{if(event.target?.matches?.('.conversation-list'))cancel();},true);
 document.addEventListener('dragstart',event=>{if(event.target.closest('.conversation-item'))event.preventDefault();});
 document.addEventListener('contextmenu',event=>{if(event.target.closest('.conversation-item')&&(hold||Date.now()<until))event.preventDefault();});
 document.addEventListener('click',event=>{const row=event.target.closest('.conversation-item[data-id]');if(H.route()!=='inbox'||!row||event.target.closest('input,button,a'))return;if(row.dataset.id===heldId&&Date.now()<until){event.preventDefault();event.stopImmediatePropagation();return;}if(selectionMode){event.preventDefault();event.stopImmediatePropagation();toggle(row.dataset.id);}},true);
}
function paint(){openMenus=[...document.querySelectorAll('.chat-menu[open]')].map(m=>m.querySelector('summary').getAttribute('aria-label')||m.querySelector('summary').textContent);skipCapture=true;try{H.render();}finally{skipCapture=false;}}
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
const b=(label,action,id='',extra='')=>`<button type="button" class="btn small" data-chat="${action}" data-id="${e(id)}" ${extra}>${label}</button>`;
const sel=(label,name,items,value)=>`<label>${label}<select name="${name}" class="input">${items.map(([v,t])=>`<option value="${e(v)}" ${String(v)===String(value)?'selected':''}>${e(t)}</option>`).join('')}</select></label>`;
const active=()=>H.state.conversations.find(c=>c.id===$('#reply-form')?.dataset.id);
const date=v=>v?new Date(v).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}):'—';
const storageKey=()=>`chat-drafts:${H?.state.user.id}`;
const freshDraft=()=>({text:'',note:false,quoteId:'',assetIds:[],assignedStaffId:'',mentionName:'',groupMentions:[],groupText:''});
function draft(id){if(!drafts.has(id))drafts.set(id,freshDraft());return drafts.get(id);}
function saveDrafts(){try{sessionStorage.setItem(storageKey(),JSON.stringify([...drafts]));}catch{}}
export function rememberInboxDraft(){const form=$('#reply-form');if(skipCapture||!H||H.route()!=='inbox'||!form)return;openMenus=[...document.querySelectorAll('.chat-menu[open]')].map(m=>m.querySelector('summary').getAttribute('aria-label')||m.querySelector('summary').textContent);const d=draft(form.dataset.id);captureGroupMentions(d,form.elements.text.value);d.text=form.elements.text.value;d.note=form.elements.note.checked;saveDrafts();}
export function inboxUnreadCount(S,q=''){return unreadThreadCount(S,q,F);}
export function inboxThreads(S,q,status){if(q!==listQuery){threadLimit=150;listQuery=q;}const threads=filterThreads(S,q,status,F);totalThreads=threads.length;return threads.slice(0,threadLimit);}
export function chatMessages(messages,conv,S,previous=null){
 const messageQuery=conv.id===lastConv?searchIn:'';const messageIndex=new Map([...(S.quoteMessages||[]),...S.messages].map(m=>[m.id,m])),users=new Map(S.users.map(u=>[u.id,u])),customers=new Map(S.customers.map(c=>[c.id,c])),mentions=new Map();for(const t of S.chatMentions||[]){if(!t.messageId)continue;const name=t.assignedStaffName||users.get(t.assignedStaffId)?.name||'Chưa phân công';mentions.set(t.messageId,[...new Set([...(mentions.get(t.messageId)||[]),name])]);}const ordered=chronologicalMessages(messages),timeline=messageTimeline(previous?[previous,...ordered]:ordered);return ordered.map(m=>{
  const timing=timeline.get(m.id),header=timing.separator?`<div class="chat-day">${e(timing.separator)}</div>`:'';
  const quote=messageIndex.get(m.quoteId),attachments=(m.attachments||[]).map(a=>{const url=safeLink(a.url);if(!url)return '';return `<a class="chat-attachment" href="${e(url)}" target="_blank" rel="noopener noreferrer">${a.type==='image'?`<img src="${e(url)}" alt="${e(a.name||'Ảnh')}" loading="lazy" referrerpolicy="no-referrer">`:a.type==='video'?`<span>▶ ${e(a.name||'Video')}</span>`:`<span>📎 ${e(a.name||'Tệp')}</span>`}</a>`;}).join('');
  const state={internal:'Ghi chú nội bộ',accepted:'API đã nhận',received:'Đã nhận',sent:'Đã gửi',sending:'Đang gửi',failed:'Gửi lỗi',unknown:'Cần kiểm tra trên Zalo',demo:'Mô phỏng'}[m.status]||m.status;
  return header+`<div class="bubble-wrap ${e(m.direction)} ${m.status==='failed'?'message-failed':''} ${timing.firstMinute?'message-first-minute':''} ${mentions.has(m.id)?'message-task-pending':''}" data-message="${e(m.id)}" data-first-minute="${timing.firstMinute}" data-message-version="${e(m.version?JSON.stringify([m.version,quote?.version,users.get(m.actor)?.name,customers.get(conv.customerId)?.name,mentions.get(m.id),messageQuery,timing.firstMinute]):'')}" ${messageQuery&&!normalize(m.text).includes(normalize(messageQuery))?'hidden':''}>
  ${m.senderType==='ai'?`<small class="message-sender">AI · ${e(S.chatbots?.find(b=>b.id===m.botId)?.name||'Chatbot')}</small>`:''}${m.senderType!=='ai'&&(conv.threadType===1)?`<strong class="message-sender">${e(m.senderName||(m.direction==='incoming'?(conv.threadType===1?'Thành viên':customers.get(conv.customerId)?.name):users.get(m.actor)?.name)||(m.direction==='incoming'?'Khách':'Bạn'))}</strong>`:''}
  <div class="bubble" title="Nhấn giữ để sao chép">${quote?`<button type="button" class="quote-block" data-chat="jump" data-id="${e(quote.id)}">↪ ${e(quote.text?.slice(0,200))}</button>`:''}${(richMessage(m,S,conv)??('<span>'+renderChatText(m,S,conv)+'</span>'+attachments))+linkPreviewSlots(m)}${mentions.has(m.id)?`<small class="message-task-assignees" aria-label="Nhân viên đang xử lý">- ${e(mentions.get(m.id).join(', '))}</small>`:''}<small class="message-info"><time datetime="${e(m.createdAt)}">${e(timing.time)}</time>${['failed','sending','unknown'].includes(m.status)?' · '+e(state):''}${m.error?' · '+e(m.error):''}</small></div>
  <div class="message-tools">${m.status==='failed'&&m.direction==='outgoing'&&!m.retryMessageId?b('↻ Gửi lại','retry-message',m.id,'aria-label="Gửi lại tin nhắn lỗi"'):m.retryMessageId?'<small>Đã tạo lượt gửi lại</small>':''}${m.direction!=='note'?b('↩ Trả lời','quote',m.id)+b('Chuyển tiếp','forward',m.id):''}${b('Sao chép','copy',m.id)}${b(m.pinned?'Bỏ ghim nội bộ':'Ghim nội bộ','pin-message',m.id)}${b('Nhắc việc','remind-message',m.id)}</div></div>`;
 }).join('');
}
export function syncChatPins(){
 const chat=$('.chat-messages'),id=$('#reply-form')?.dataset.id;if(!chat||!id||!H?.state)return;
 const old=$('.chat-pins'),opened=old?.open;old?.remove();
 const c=H.state.conversations.find(c=>c.id===id);if(!c)return;const pins=pinnedRows(H.state,c);
 if(pins.length)chat.insertAdjacentHTML('beforebegin',`<details class="chat-pins" ${opened?'open':''}><summary>📌 Danh sách ghim (${pins.length})<span>${e(pins[0].text||'Ảnh / video / tệp')}</span></summary><div class="chat-pin-list">${pins.map(m=>`<div class="chat-pin-row"><div class="chat-pin-content">${m.available?b(e(m.text||'Ảnh / video / tệp'),'jump',m.id):'<span>'+e(m.text||'Ảnh / video / tệp')+'</span>'}<small>${e(m.senderName||'Tin nhắn')} · ${m.remote?'Zalo':'Ghim nội bộ'}${m.attachments?.length?' · '+m.attachments.length+' tệp':''}</small></div>${m.remote?b('Bỏ ghim','unpin-platform',m.topicId):b('Bỏ ghim','pin-message',m.id)}</div>`).join('')}</div></details>`);
}
